func (this *Derive) ParseMarket(market any) any {
	var typeVar any = this.SafeString(market, "instrument_type")
	var marketType any = nil
	var spot bool = false
	var margin bool = true
	var swap bool = false
	var option bool = false
	var linear any = nil
	var inverse any = nil
	var baseId any = this.SafeString(market, "base_currency")
	var quoteId any = this.SafeString(market, "quote_currency")
	var base any = this.SafeCurrencyCode(baseId)
	var quote any = this.SafeCurrencyCode(quoteId)
	var marketId any = this.SafeString(market, "instrument_name")
	var symbol any = Add(Add(base, "/"), quote)
	var settleId any = nil
	var settle any = nil
	var expiry any = nil
	var strike any = nil
	var optionType any = nil
	var optionLetter any = nil
	if IsTrue(IsEqual(typeVar, "erc20")) {
		spot = true
		marketType = "spot"
	} else if IsTrue(IsEqual(typeVar, "perp")) {
		margin = false
		settleId = "USDC"
		settle = this.SafeCurrencyCode(settleId)
		symbol = Add(Add(Add(Add(base, "/"), quote), ":"), settle)
		swap = true
		linear = true
		inverse = false
		marketType = "swap"
	} else if IsTrue(IsEqual(typeVar, "option")) {
		settleId = "USDC"
		settle = this.SafeCurrencyCode(settleId)
		margin = false
		option = true
		marketType = "option"
		var optionDetails any = this.SafeDict(market, "option_details")
		expiry = this.SafeTimestamp(optionDetails, "expiry")
		strike = this.SafeInteger(optionDetails, "strike")
		optionLetter = this.SafeString(optionDetails, "option_type")
		symbol = Add(Add(Add(Add(Add(Add(Add(Add(Add(Add(base, "/"), quote), ":"), settle), "-"), this.Yymmdd(expiry)), "-"), this.NumberToString(strike)), "-"), optionLetter)
		if IsTrue(IsEqual(optionLetter, "P")) {
			optionType = "put"
		} else {
			optionType = "call"
		}
		linear = true
		inverse = false
	}
	var contractSize any = Ternary(IsTrue((spot)), nil, 1)
	var isContract bool = (IsTrue(swap) || IsTrue(option))
	return this.SafeMarketStructure(map[string]any{
		"id":             marketId,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           marketType,
		"spot":           spot,
		"margin":         margin,
		"swap":           swap,
		"future":         false,
		"option":         option,
		"active":         this.SafeBool(market, "is_active"),
		"contract":       isContract,
		"linear":         linear,
		"inverse":        inverse,
		"contractSize":   contractSize,
		"expiry":         expiry,
		"expiryDatetime": this.Iso8601(expiry),
		"taker":          this.SafeNumber(market, "taker_fee_rate"),
		"maker":          this.SafeNumber(market, "maker_fee_rate"),
		"strike":         strike,
		"optionType":     optionType,
		"precision": map[string]any{
			"amount": this.SafeNumber(market, "amount_step"),
			"price":  this.SafeNumber(market, "tick_size"),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": this.SafeNumber(market, "minimum_amount"),
				"max": this.SafeNumber(market, "maximum_amount"),
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	})
}

